-- Arbeitsrecht Berufsbildung > Soziale gesellschaftliche Themen > Nachhaltigkeit > Energieeinsparung
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch energieeffiziente Hardware Energie einsparen?', 2, '[{"text": "Ja", "correct": true, "because": "Energieeffiziente Geräte verbrauchen weniger Strom"}, {"text": "Nein", "correct": false, "because": "Einsparung ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Energieeinsparung in einem IT-Betrieb für die Nachhaltigkeit relevant?', 2, '[{"text": "Ja", "correct": true, "because": "Reduzierter Energieverbrauch schont Ressourcen"}, {"text": "Nein", "correct": false, "because": "Nachhaltigkeit umfasst Energieeinsparung"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Fachinformatiker Maßnahmen zur Energieeinsparung im Betrieb umsetzen?', 2, '[{"text": "Ja", "correct": true, "because": "Teil der betrieblichen Nachhaltigkeitsstrategie"}, {"text": "Nein", "correct": false, "because": "Umsetzung ist üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch Virtualisierung von Servern Energie einsparen?', 2, '[{"text": "Ja", "correct": true, "because": "Weniger physische Server reduzieren Stromverbrauch"}, {"text": "Nein", "correct": false, "because": "Virtualisierung spart Energie"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Energieeinsparung in einem IT-Betrieb nur mit hohen Kosten verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Langfristig können Kosten gesenkt werden"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig teuer"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme fördert die Energieeinsparung in einem IT-Betrieb?', 2, '[{"text": "Energieeffiziente Hardware", "correct": true, "because": "Reduziert Stromverbrauch"}, {"text": "Dauerbetrieb von Geräten", "correct": false, "because": "Erhöht Verbrauch"}, {"text": "Keine Abschaltfunktion", "correct": false, "because": "Verschwendet Energie"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel der Energieeinsparung in einem IT-Betrieb?', 3, '[{"text": "Reduktion des CO2-Ausstoßes", "correct": true, "because": "Nachhaltigkeit zielt auf Umweltschutz"}, {"text": "Erhöhung der Arbeitszeit", "correct": false, "because": "Kein Ziel"}, {"text": "Steigerung der Kosten", "correct": false, "because": "Kosten sollen gesenkt werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie unterstützt die Energieeinsparung in einem IT-Betrieb?', 3, '[{"text": "Server-Virtualisierung", "correct": true, "because": "Weniger physische Server, weniger Strom"}, {"text": "Alte Hardware", "correct": false, "because": "Verbraucht mehr Energie"}, {"text": "Manuelle Prozesse", "correct": false, "because": "Keine Energieeinsparung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist in einem IT-Betrieb für die Umsetzung von Energieeinsparmaßnahmen verantwortlich?', 2, '[{"text": "Das Management", "correct": true, "because": "Entscheidet über Strategien"}, {"text": "Nur Auszubildende", "correct": false, "because": "Nicht deren alleinige Aufgabe"}, {"text": "Die Kunden", "correct": false, "because": "Kunden haben keine Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich durch Energieeinsparung für einen IT-Betrieb?', 3, '[{"text": "Kostensenkung", "correct": true, "because": "Weniger Stromverbrauch spart Geld"}, {"text": "Höhere Arbeitsbelastung", "correct": false, "because": "Kein Vorteil"}, {"text": "Geringere Produktivität", "correct": false, "because": "Produktivität bleibt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fördern die Energieeinsparung in einem IT-Betrieb?', 4, '[{"text": "Energieeffiziente Hardware", "correct": true, "because": "Reduziert Stromverbrauch"}, {"text": "Server-Virtualisierung", "correct": true, "because": "Weniger Server, weniger Energie"}, {"text": "Dauerbetrieb von Geräten", "correct": false, "because": "Erhöht Verbrauch"}, {"text": "Standby-Modus nutzen", "correct": true, "because": "Spart Energie bei Nichtnutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Energieeinsparung einem IT-Betrieb?', 3, '[{"text": "Kostensenkung", "correct": true, "because": "Weniger Stromkosten"}, {"text": "Verbessertes Umweltimage", "correct": true, "because": "Nachhaltigkeit stärkt Reputation"}, {"text": "Höhere Arbeitsbelastung", "correct": false, "because": "Kein Vorteil"}, {"text": "Reduktion des CO2-Ausstoßes", "correct": true, "because": "Umweltschutz wird gefördert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile können durch Energieeinsparmaßnahmen in einem IT-Betrieb entstehen?', 4, '[{"text": "Kurzfristige Anschaffungskosten", "correct": true, "because": "Neue Hardware kostet Geld"}, {"text": "Komplexere Verwaltung", "correct": true, "because": "Maßnahmen erfordern Planung"}, {"text": "Weniger Effizienz", "correct": false, "because": "Effizienz bleibt oder steigt"}, {"text": "Zeitaufwand für Umstellung", "correct": true, "because": "Umsetzung braucht Zeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien unterstützen die Energieeinsparung in einem IT-Betrieb?', 3, '[{"text": "Energieeffiziente Prozessoren", "correct": true, "because": "Reduzieren Stromverbrauch"}, {"text": "Cloud Computing", "correct": true, "because": "Optimiert Ressourcennutzung"}, {"text": "Alte Server", "correct": false, "because": "Verbrauchen mehr Energie"}, {"text": "Standby-Funktionen", "correct": true, "because": "Sparen Energie bei Nichtnutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen Energieeinsparung für einen IT-Betrieb wichtig?', 3, '[{"text": "Umweltschutz", "correct": true, "because": "Reduziert CO2-Ausstoß"}, {"text": "Kosteneffizienz", "correct": true, "because": "Senkt Betriebskosten"}, {"text": "Geringere Produktivität", "correct": false, "because": "Kein Aspekt"}, {"text": "Nachhaltigkeitsziele", "correct": true, "because": "Teil der Strategie"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Energieeinsparung reduziert den Stromverbrauch in einem IT-Betrieb. b) Energieeinsparung erhöht immer die Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Stromverbrauch ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Server-Virtualisierung spart Energie in einem IT-Betrieb. b) Fachinformatiker tragen zur Energieeinsparung bei.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Virtualisierung und Fachkräfte"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Energieeinsparung verbessert das Umweltimage eines IT-Betriebs. b) Energieeinsparung ist nur mit hohen Kosten verbunden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Image ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Energieeffiziente Hardware fördert die Energieeinsparung in einem IT-Betrieb. b) Standby-Modus hat keinen Einfluss auf den Energieverbrauch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Energieeinsparung kann die Betriebskosten eines IT-Betriebs senken. b) Das Management ist für die Umsetzung verantwortlich.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Kostensenkung und Management"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');

